#define STRICT_LIBRARY
#include "strict.cpp"
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
string flip(string s){auto p=s.find('v');return s.substr(p+1)+"v"+s.substr(0,p);}
struct Path{int z;vector<string> m;};map<string,pair<int,bool>> lookup;
string key(const Path&p){string k=to_string(p.z);for(auto&m:p.m)k+="/"+m;return k;}
Path canon(Path p){if(lookup.at(p.m[0]).second){p.z=-p.z;for(auto&m:p.m)m=flip(m);}return p;}
Path tail(Path p){p.m.erase(p.m.begin());return canon(p);}
struct Row{int nw=0;uint64_t*data=nullptr;size_t bytes=0;vector<Path> paths;map<string,int> ix;vector<U> first;uint64_t*get(U a){return data+(size_t)a*nw;}bool has(U a,int k){return (get(a)[k/64]>>(k%64))&1;}};
vector<Row> rows;set<tuple<string,string,int>> edges;
struct Link{int dst,src;};
void calcpaths(int id){auto&t=ts[id];auto&r=rows[id];int n=r.paths.size();if(!n)return;r.nw=(n+63)/64;r.bytes=(size_t)t.sz*r.nw*8;string file="mask_"+t.name+".bin";int fd=open(file.c_str(),O_RDWR);assert(fd>=0);r.data=(uint64_t*)mmap(nullptr,r.bytes,PROT_READ|PROT_WRITE,MAP_SHARED,fd,0);assert(r.data!=MAP_FAILED);close(fd);r.first.assign(n,UINT32_MAX);
vector<vector<Link>> links(ts.size()*6);for(int k=0;k<n;k++){auto&p=r.paths[k];auto[j,sw]=lookup.at(p.m[1]);int src=-1;if(p.m.size()>2){auto s=tail(p);auto it=rows[j].ix.find(key(s));assert(it!=rows[j].ix.end());src=it->second;}links[(j*2+sw)*3+p.z+1].push_back({k,src});}
vector<D> orig(t.sz);ifstream ff("dist_"+t.name+".bin",ios::binary);ff.read((char*)orig.data(),2ull*t.sz);assert(ff.gcount()==2ull*t.sz);vector<vector<U>> bins(128);bool active[3]={};for(auto&p:r.paths)active[p.z+1]=true;auto&d=ds[id];for(U a=0;a<(U)t.sz;a++){if(t.v[a]!=0||orig[a]<=8||!active[1])continue;assert(d[a]<bins.size());bins[d[a]].push_back(a);}
vector<uint64_t> accum(r.nw);long long processed=0;for(int k=1;k<(int)bins.size();k++){for(U a:bins[k]){int z=t.v[a];Pos p=dec(t,a);auto out=r.get(a);fill(accum.begin(),accum.end(),0);moves(t,p,[&](Move m,Pos v){auto[j,q]=child(t,p,m,v);U b=enc(ts[j],q);if(ds[j][b]!=k-1)return;bool sw=q.turn!=1-p.turn;int y=pc(ts[j].v[b])*(sw?-1:1);if(y!=z)return;if(m.cap<0&&!m.pr){auto in=r.get(b);for(int l=0;l<r.nw;l++)accum[l]|=in[l];return;}for(auto l:links[(j*2+sw)*3+z+1])if(l.src<0||rows[j].has(b,l.src))accum[l.dst/64]|=1ull<<(l.dst%64);});for(int l=0;l<r.nw;l++){out[l]=accum[l];if(!accum[l])continue;uint64_t b=accum[l];while(b){int x=__builtin_ctzll(b);b&=b-1;int q=l*64+x;if(r.first[q]==UINT32_MAX)r.first[q]=a;}}processed++;}vector<U>().swap(bins[k]);}for(U a=0;a<(U)t.sz;a++){if(t.v[a]==INV||t.v[a]==DEAD||!active[t.v[a]+1])continue;auto row=r.get(a);for(int l=0;l<r.nw;l++){uint64_t b=row[l];while(b){int x=__builtin_ctzll(b);b&=b-1;int q=l*64+x;if(r.first[q]==UINT32_MAX)r.first[q]=a;}}}msync(r.data,r.bytes,MS_ASYNC);cerr<<t.name<<" paths "<<n<<" processed "<<processed<<" yes "<<count_if(r.first.begin(),r.first.end(),[](U x){return x!=UINT32_MAX;})<<endl;}
struct Step{int id;Pos p;Move m;bool sw;};
bool witness(Path path,int id,Pos p,bool overall,vector<Step>&out){path=canon(path);if(path.m.size()==1)return true;auto&t=ts[id];auto&r=rows[id];int k=r.ix.at(key(path));assert(r.has(enc(t,p),k));for(;;){int d=getd(id,p),z=path.z;bool found=false,change=false;Move em{};Pos ep{};int eid=-1;moves(t,p,[&](Move m,Pos v){if(found)return;auto[j,q]=child(t,p,m,v);U b=enc(ts[j],q);if(ds[j][b]!=d-1)return;bool sw=q.turn!=1-p.turn;if(pc(ts[j].v[b])*(sw?-1:1)!=z)return;if(m.cap<0&&!m.pr){if(!r.has(b,k))return;}else{if(mat(ts[j],sw)!=path.m[1])return;if(path.m.size()>2&&!rows[j].has(b,rows[j].ix.at(key(tail(path)))))return;change=true;}found=true;em=m;ep=q;eid=j;});assert(found);out.push_back({id,p,em,overall});if(change)return witness(tail(path),eid,ep,overall^(ep.turn!=1-p.turn),out);p=ep;}}
int main(){init();setup();load();loadD();for(int i=0;i<(int)ts.size();i++){auto&t=ts[i];string f=(t.name=="KPvKP"?"rep3_":"rep4_")+t.name+".bin";ifstream in(f,ios::binary);in.read((char*)ds[i].data(),2ull*t.sz);assert(in.gcount()==2ull*t.sz);}rows.resize(ts.size());for(int i=0;i<(int)ts.size();i++){lookup[mat(ts[i])]={i,false};if(mat(ts[i],true)!=mat(ts[i]))lookup[mat(ts[i],true)]={i,true};}ifstream ef("strict_edges_canon.tsv");string line;while(getline(ef,line)){stringstream s(line);string a,b,z;getline(s,a,'\t');getline(s,b,'\t');getline(s,z,'\t');edges.insert({a,b,stoi(z)});edges.insert({flip(a),flip(b),-stoi(z)});}ifstream f("path_input.tsv");map<string,Path> all;while(getline(f,line)){stringstream ss(line);string z,m,st;getline(ss,z,'\t');getline(ss,m,'\t');getline(ss,st,'\t');stringstream mm(m);Path p{stoi(z),{}};while(getline(mm,m,'/'))p.m.push_back(m);all[key(canon(p))]=canon(p);}for(auto&[k,p]:all){bool ok=true;for(int j=1;j<(int)p.m.size();j++)if(!edges.count({p.m[j-1],p.m[j],p.z}))ok=false;if(!ok)continue;auto&r=rows[lookup.at(p.m[0]).first];r.ix[k]=r.paths.size();r.paths.push_back(p);}for(int i=0;i<(int)ts.size();i++)calcpaths(i);ofstream o("repeat_paths_canon.tsv");for(auto&[k,p]:all){int id=lookup.at(p.m[0]).first;auto&r=rows[id];auto it=r.ix.find(k);bool yes=it!=r.ix.end()&&r.first[it->second]!=UINT32_MAX;o<<k<<'\t'<<(yes?"YES":"NO");if(yes){vector<Step> steps;assert(witness(p,id,dec(ts[id],r.first[it->second]),false,steps));for(auto&s:steps)o<<'\t'<<s.sw<<':'<<fen(ts[s.id],s.p)<<':'<<uci(s.p,s.m);}o<<'\n';}cerr<<"finished "<<all.size()<<endl;}
